import pathlib,json,hashlib,zipfile,shutil,sys
f=pathlib.Path(sys.argv[1]);R=pathlib.Path(sys.argv[2]);assert f.stat().st_size==16563;assert hashlib.sha256(f.read_bytes()).hexdigest()=='f0f1fa3d8110a9d5d82403eeed9b9d6b30a7aed8a7a54f0e201da0e5b1aa3887';R.mkdir(parents=True,exist_ok=True)
with zipfile.ZipFile(f) as z:
 m=json.loads(z.read('files-sha256.json'));assert len(z.namelist())==9 and set(z.namelist())==set(m)|{'files-sha256.json'}
 for n,v in m.items():
  p=pathlib.PurePosixPath(n);assert not p.is_absolute() and '..' not in p.parts;b=z.read(n);assert len(b)==v['bytes'] and hashlib.sha256(b).hexdigest()==v['sha256'];p=R/n;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(b)
for p in (R/'auditor-shared-source').rglob('*.go'):assert p.read_bytes()==pathlib.Path(p.relative_to(R/'auditor-shared-source')).read_bytes()
C=json.loads((R/'source-muhash/census.json').read_text());H=json.loads((R/'source-muhash/head.json').read_text());S=json.loads((R/'source-muhash/status.json').read_text());pre=json.loads(pathlib.Path('build/benchmarks/20261028-full-state-acceptance/downloaded-prelude/source-muhash/head.json').read_text());assert H==pre;assert C['complete'] and C['muhash_verified'] and S['complete'] and S['head_unchanged'] and S['normalized_state_and_digest_verified'];assert (C['block_num'],C['tx_num'],C['block_hash'],C['muhash_root'])==(H['BlockNum'],H['TxNum'],H['BlockHash'],H['Root']);state=bytes(H['State']);assert len(state)==384 and 0<int.from_bytes(state,'little')<(1<<3072)-1103717 and hashlib.sha256(state).digest()==bytes(H['Root']);assert C['source_rows']==[119819707,389068,1036811084];assert C['total_kv']['rows']==sum(v['rows'] for v in C['classes'].values()) and C['classes']['future']['rows']==0
D=pathlib.Path(__file__).parent;p=D/'source-muhash';p.mkdir(exist_ok=True)
for n in ['head.json','census.json','status.json']:shutil.copyfile(R/'source-muhash'/n,p/n)
receipt={'complete':True,'scope':'native full source fold receipt and shared source code; local metadata/normalized-state digest consistency, not a second local billion-row fold','archive_bytes':f.stat().st_size,'archive_sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'members':9,'source_rows':C['source_rows'],'total_source_rows':sum(C['source_rows']),'source_logical_bytes':C['source_logical_bytes'],'seconds_native_full_fold':S['seconds'],'head':H['BlockNum'],'tx':H['TxNum'],'root':bytes(H['Root']).hex(),'normalized_state_sha256':hashlib.sha256(state).hexdigest()};(D/'source-muhash/local-verification.json').write_text(json.dumps(receipt,indent=2));print(json.dumps(receipt,indent=2))
